# Append Q9 results to /output/report.json (idempotent: drops earlier Q9 entries).
import json
P='/output/report.json'; r=json.load(open(P))
r['results']=[x for x in r['results'] if 'Q9' not in x.get('evidence','')]
r['recipe']=[s for s in r['recipe'] if 'scripts/q9_vel.py' not in s.get('scripts',[])]
if 'Q9 (velocity-resolved' in r['interpretation']: r['interpretation']=r['interpretation'].split('\n\nQ9 (velocity-resolved')[0]
r['caveats']=[c for c in r['caveats'] if not c.startswith('Q9:')]
A=[{"name":"convention","value":"Jy ratio at a common circular beam (Tb ratio = x1.0126), 40 km/s bins (9 channels), velocity relative to VSYS=2780 km/s (radio, LSRK), linear baseline from |v|=520-2000 km/s, S/N>3 in both lines per bin, noise from random line-free bins/positions in the same aperture"},
   {"name":"centres","value":"HCO+ +-350 km/s peak near N(0,+2.55\") and S(-0.15,-2.55\") offsets from 156.96346,-43.90461; Bridge (0.3,0.15\")"}]
def add(q,v,u,c,ev,t,unit="ratio",extra=None):
    r['results'].append({"quantity":q,"value":v,"uncertainty":u,"unit":unit,"assumptions":A+(extra or []),"confidence":c,"evidence":ev+" | Q9","target":t})
add("Velocity-resolved HCN/HCO+ 3-2 at N, nuclear core (Xb4b @0.30\", r<0.25\")",
 "0.98 +- 0.02 (stat) averaged; 0.97/0.98/0.98 in blue (<-60)/core (|v|<60)/red (>+60 km/s) wings; per 40 km/s bin flat within errors (chi2/dof 13/7, slope -0.02+-0.02 per 100 km/s)",
 "statistical +-0.02; array-recovery systematic <~10% on ratios (p0008)","medium","scripts/q9_vel.py -> out/q9/q9_vel.log, q9_vel_ratio.csv, q9_constancy.csv","N peak (r<0.25\")")
add("Velocity-resolved HCN/HCO+ 3-2 at N, radial x velocity (Xb4b @0.30\")",
 "r<0.25\": 0.98 flat; 0.25-0.5\": 0.84 (blue 0.82, core 0.83, red 0.90); 0.5-1\": 0.65 (0.645/0.645/0.72). Ratio is constant with velocity at each radius to <~10% (slopes +0.02+-0.015 per 100 km/s) while the radius dependence is 0.98->0.65",
 "stat +-0.01-0.03 per bin","medium","scripts/q9_vel.py -> out/q9/q9_vel.log","N, r<1\"")
add("Velocity-resolved HCN/HCO+ 3-2 at N (Xb4d @1.05\" matched beam), annuli 0-0.5/0.5-1/1-2\"",
 "0.78/0.71/0.52 (weighted means). Blue wing (-120..-60) 0.74/0.68/0.57, core (|v|<60) 0.78/0.70/0.51, red wing (+78..+120) 0.93/0.85/0.59. Core is NOT lower than the blue wing; a mild rise toward the red line edge (slope +0.08+-0.006 per 100 km/s at r<0.5\", chi2/dof 269/7 for constant) is present at 1.05\" but absent at 0.30\" in the nucleus (0.97 blue vs 0.98 red), so it is mainly beam/spatial mixing of a high-ratio core with kinematically offset, lower-ratio gas",
 "stat +-0.006-0.05 per bin; centroid and region definition systematic","medium","scripts/q9_vel.py -> out/q9/q9_vel.log, q9_constancy.csv","N, r<2\"")
add("Velocity-resolved HCN/HCO+ 3-2 at S (Xb4d @1.05\", Xb4b @0.30\"): is the S deficit present at all velocities?",
 "Yes within the detected range (-120..+120 km/s). Xb4d 0-0.5/0.5-1/1-2\": weighted mean 0.38/0.36/0.36; blue/core/red = 0.38/0.39/0.38, 0.35/0.36/0.40, 0.36/0.35/0.44; slope -0.002+-0.007, +0.023+-0.007, +0.032+-0.011 per 100 km/s. Xb4b 0.25\" r<0.25\": 0.44 (0.44/0.44/0.27+-0.1). Individual 40-km/s bins scatter 0.28-0.46 (chi2/dof 43/9) but with no systematic core-vs-wing pattern. Outside |v|>150 km/s the ratio is 0.5-0.7 with errors 0.07-0.23 (<2 sigma above 0.37) and HCN is undetected beyond that: no evidence for or against recovery of the ratio in S wings",
 "stat +-0.006-0.03 per bin; array-recovery <~10%","medium","scripts/q9_vel.py -> out/q9/q9_vel.log, q9_constancy.csv","S peak and r<2\"")
add("Velocity-resolved HCN/HCO+ 3-2 in the Bridge (Xb4d @1.05\", r<1\" about (0.3,0.15\"))",
 "0.45 weighted mean (blue 0.42, core 0.455, red 0.39); central bins 0.37-0.48 (+-0.01); extreme bins (|v|~120) 0.66+-0.13, 0.84+-0.22 (noise-limited). Same overall pattern as S: no core dip",
 "stat +-0.005-0.2","medium","scripts/q9_vel.py -> out/q9/q9_vel.log","Bridge")
add("HCN vs HCO+ line-profile widths at the nuclei (spectral aperture r<0.5\" Xb4d @1.05\" / r<0.25\" Xb4b @0.30\", +-400 km/s)",
 "N: FWHM HCN 177 vs HCO+ 167 km/s (1.05\"); 152 vs 112 km/s (0.30\" r<0.25\", asymmetric/noisy); sigma(2nd moment) 77 vs 66 km/s. S: FWHM 81 vs 90; 88 vs 95 (Xb4b); sigma 100 vs 81 km/s (HCN 2nd moment larger because of low-level wings, FWHM not). Centroids N ~0 to +13 km/s, S -27 to -55 km/s. HCN and HCO+ have the same core width at N within ~10%; at S HCN is not narrower in FWHM (89/90) so the earlier 'S HCN narrower' reading from peak ratios (0.52 vs integrated 0.42) comes from channel-to-channel ratio structure (0.45 in blue half vs 0.37 near v~0), not a width difference",
 "FWHM +-10-20 km/s (channel 4.4 km/s, noise); 2nd moments depend on baseline wings","low","scripts/q9_vel.py -> out/q9/q9_profiles.csv","N, S",unit="km/s")
add("Velocity-resolved 4-3/3-2 (Tb) per molecule at a common 6.5\" beam, nuclei merged (Xb47/Xb4f, midpoint spectrum)",
 "HCN: 0.41+-0.004 over +-250 km/s (core |v|<100 0.409, blue -250..-100 0.43+-0.07, red 100..250 0.38+-0.03); per-bin 0.36-0.48 near the core (0.46 at -70, 0.39 at -30, 0.36 at +10, 0.43 at +50, 0.39 at +90). HCO+: 0.495+-0.002 (core 0.502; blue 0.47+-0.05; red 0.37+-0.03); per bin 0.44-0.54 at -110..+50 then 0.38 at +90 and 0.37 at +130. HCN/HCO+ 4-3/3-2 double ratio ~0.83 in the core and ~1.0 in the red wing. Wings (|v|>150) noise-limited",
 "stat <=0.01 in the core (+-0.03-0.1 in wings); beams differ in native size (Xb47 4.1x2.7, Xb4f 5.7x3.5 -> 6.5\"), no flux-recovery correction (<~10% ladder systematic, p0008); red-side drop coincides with N-dominated gas and with spatial mixing of N and S at 6.5\", so not a pure velocity effect","medium","scripts/q9_ladder.py -> out/q9/q9_ladder.log, q9_ladder_vel.csv","N+S merged (6.5\")",
 extra=[{"name":"rest frequencies (GHz)","value":"HCN 3-2 265.886434, 4-3 354.505477; HCO+ 3-2 267.557626, 4-3 356.734223 (Splatalogue/CDMS, as used in q1_lib)"}])
r['interpretation']+=("\n\nQ9 (velocity-resolved ratios): HCN/HCO+ 3-2 does not drop where the line is brightest. At N the ratio is flat with velocity at fixed radius in the nuclear core (0.98 at 0.30\", r<0.25\"; 0.84 and 0.65 at 0.25-0.5\" and 0.5-1\"), "
 "and at 1.05\" the core is equal to or slightly below (~5%) the blue wing and 15-20% below the red edge; at S the ratio is 0.35-0.44 in every velocity bin detected in both lines. The strongest variation is therefore spatial (radius), not spectral. "
 "For two thick lines, an opacity-driven N rise would require the core channels (highest tau) to show a different ratio from the wings; they do not, which favours (but does not prove) a ratio set by excitation/abundance of a gas component whose line shape is similar for both molecules, i.e. the N-S contrast and the N radial gradient are not a line-core saturation effect. "
 "Two-phase (Michiyama+2018) velocity-resolved signatures are not seen at S in the line range detected in both lines (>3 sigma); the extreme blue wing ratios (0.5-0.7) are consistent with both the core value and a higher outflow-like value. The 4-3/3-2 ratio per molecule is ~constant within ~10-15% across the core of each line at 6.5\" (HCN 0.41, HCO+ 0.50) and drops in the red wing, but the N/S spatial mixing at 6.5\" prevents a clean velocity reading.")
r['caveats'].append("Q9: errors are statistical (random line-free bins/positions in the same aperture); bins within an aperture are independent but apertures at the same centre are nested/correlated. Pointing: HCN and HCO+ peaks can differ by <~0.1\" (HCO+ centre adopted). Spatial and spectral mixing at 1.05\" cannot be separated (rising red-edge ratio at N at 1.05\" vanishes at 0.30\"). Ratios are flux/brightness-temperature ratios of thick lines; flat spectral ratio does not separate abundance from excitation. 4-3/3-2 at 6.5\" merges N and S and has no flux-recovery correction. HCN v2=1f (+401 km/s in the HCO+ frame) lies outside the +-450 km/s range used; wings beyond +-150 km/s are noise-limited in HCN at S/Bridge.")
r['recipe'].append({"order":max(s['order'] for s in r['recipe'])+1,"stage":"measurement","description":"Q9: channel-resolved HCN/HCO+ 3-2 from cached Xb4d/Xb4b cubes (q7_cache.py), each channel convolved to 1.05\" (Xb4d) or 0.30\" (Xb4b), aperture sums in annuli about the N, S, Bridge centres, rebinned to 40 km/s, linear baseline from |v|=520-2000 km/s, noise from 400 random line-free positions/bins, S/N>3 masks, weighted-constant and linear-slope tests, core/blue/red averages, FWHM and 2nd-moment widths; 4-3/3-2 per molecule at 6.5\" (Xb47, Xb4f) with Tb conversion (nu32/nu43)^2.","scripts":["scripts/q9_vel.py","scripts/q9_ladder.py","scripts/build_report_q9.py"]})
json.dump(r,open(P,'w'),indent=1)
